def f(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v==bg: continue
            for d in (1,-1):
                if 0<=r+1<h and 0<=c+d<w and g[r+1][c+d]==v:
                    # diagonal pair; extend both directions until edge or non-bg
                    for dr,dc in ((1,d),(-1,-d)):
                        rr,cc=r+1+dr,c+d+dc
                        while 0<=rr<h and 0<=cc<w and out[rr][cc]==bg:
                            out[rr][cc]=v; rr+=dr; cc+=dc
    return out
