            if v==bgg: continue
            for d in (1,-1):
                if 0<=r+1<hh and 0<=c+d<ww and g[r+1][c+d]==v:
                    # pair (r,c),(r+1,c+d): extend backward from (r,c) and forward from (r+1,c+d)
